"""Responsive compact inspection with explicit durable archive reconstruction."""
HTML=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PLN Chess · Compact evidence inspector</title><style>
:root{color-scheme:light;--ink:#142e3c;--muted:#526975;--line:#cfdbdf;--paper:#f3f6f4;--accent:#07665c}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,sans-serif}
main{max-width:1180px;margin:auto;padding:28px}nav{display:flex;gap:22px;flex-wrap:wrap;font-size:14px}a{color:var(--accent)}
header{padding:34px 0 22px}h1{font-size:clamp(30px,5vw,52px);line-height:1.12;letter-spacing:-1.5px;margin:8px 0 18px;max-width:800px}
h2{font-size:23px;margin:0 0 18px}h3{font-size:17px}.eyebrow{font-size:12px;letter-spacing:2px;font-weight:700;color:var(--accent)}
.lead{max-width:800px;font-size:18px;color:var(--muted)}.notice{border-left:4px solid #a87e25;padding:12px 18px;background:#fff8df}
.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:24px;margin:18px 0;min-width:0}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.wide{grid-column:1/-1}label{display:block;font-weight:600;font-size:14px}
input,select,textarea{display:block;width:100%;margin-top:7px;padding:10px 12px;border:1px solid #a7bdc4;border-radius:7px;font:inherit;color:var(--ink);background:white;min-width:0}
textarea{min-height:76px;resize:vertical}input:focus,select:focus,textarea:focus,button:focus-visible{outline:3px solid #62b9a7;outline-offset:2px}
button{border:1px solid #9aafb7;border-radius:7px;background:white;color:var(--ink);font:600 14px/1.4 system-ui;padding:11px 16px;cursor:pointer}
button.primary{background:var(--accent);color:white;border-color:var(--accent)}button:disabled{opacity:.45;cursor:default}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0 10px}
details{margin-top:18px}summary{cursor:pointer;font-weight:600}.muted{color:var(--muted);font-size:14px}.status{padding:12px 14px;background:#edf5f2;border-radius:7px;overflow-wrap:anywhere}.error{background:#fff0eb;color:#89351d}
.result-grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:26px}.board{display:grid;grid-template-columns:repeat(8,1fr);aspect-ratio:1;border:1px solid #6c858b;border-radius:5px;overflow:hidden;max-width:320px}
.square{display:flex;align-items:center;justify-content:center;font-size:clamp(22px,3vw,32px);line-height:1;background:#e6e6d6;color:#172b31}.square.dark{background:#93aaa4}.square.white-piece{color:white;text-shadow:0 1px 2px #001b2b,1px 0 #001b2b,-1px 0 #001b2b}
.channels{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.card{border:1px solid var(--line);border-radius:8px;padding:14px}.metric{font-size:23px;font-weight:650;margin:10px 0 0}.card small{display:block;color:var(--muted)}
.identity{font:12px/1.6 ui-monospace,monospace;overflow-wrap:anywhere}.proof-layout{display:grid;grid-template-columns:minmax(220px,1fr) minmax(0,2fr);gap:16px}.nodes{max-height:430px;overflow:auto}.node{display:block;width:100%;text-align:left;margin-bottom:6px;font:12px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}
pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf2f3;padding:16px;border-radius:7px;max-height:480px;overflow:auto;font:12px/1.6 ui-monospace,monospace;margin:0}.tags{display:flex;gap:8px;flex-wrap:wrap}.tag{background:#eaf0ef;border-radius:5px;padding:4px 8px;font-size:12px}
[hidden]{display:none!important}footer{font-size:13px;color:var(--muted);padding:20px 0 40px}
@media(max-width:720px){main{padding:16px}.panel{padding:18px}.grid,.result-grid,.proof-layout{grid-template-columns:1fr}.channels{grid-template-columns:1fr}.card{display:grid;grid-template-columns:1fr 1fr;gap:6px}.metric{margin:0}.board{width:100%;margin:auto}.actions button{flex:1 1 180px}header{padding-top:24px}.square{font-size:30px}.nodes{max-height:250px}}
</style></head><body><main>
<nav><a href="/">Legal inspector</a><a href="/preferences">Cycle 13 comparisons</a><a href="/interactions">Fields and concepts</a></nav>
<header><div class="eyebrow">PLN CHESS / CYCLE 14 / EXPERIMENTAL</div><h1>Inspect the conclusion.<br>Keep the complete evidence.</h1><p class="lead">Compare two supplied moves, inspect bounded responses, and retrieve the native proofs behind each conditional answer.</p><p class="notice">Preferences remain experimental. Legality is a separate belief, raw confidence is not a probability of correctness, and no move is selected or played.</p></header>
<section class="panel"><h2>Position and candidates</h2><form id="compare-form"><div class="grid">
<label class="wide">Registered observation<select id="example"></select></label><p class="wide muted" id="source"></p>
<label class="wide">Position · FEN<input id="fen" required spellcheck="false"></label>
<label>Candidate A · UCI<input id="move-a" required pattern="[a-h][1-8][a-h][1-8][qrbn]?" spellcheck="false"></label>
<label>Candidate B · UCI<input id="move-b" required pattern="[a-h][1-8][a-h][1-8][qrbn]?" spellcheck="false"></label>
<label>Experimental checkpoint<select id="model"></select></label><label>Legal proof mode<select id="mode"><option>operational</option><option>strict</option><option>experimental</option></select></label></div>
<details><summary>Supplied responses and observation gaps</summary><p class="muted">Supply up to three lines per candidate. Each line contains an opponent reply and an optional continuation. The candidate move is prepended. Unlisted responses remain unexamined.</p><div class="grid">
<label>After candidate A<textarea id="responses-a"></textarea></label><label>After candidate B<textarea id="responses-b"></textarea></label>
<label>Unknown squares · comma separated<input id="unknown" placeholder="e4, f5"></label><label>Native proof nodes per stage<input id="budget" type="number" min="0" max="100000" value="100000"></label></div><p id="response-source" class="muted"></p></details>
<div class="actions"><button id="compare" class="primary" type="submit">Compare moves</button><button id="continue" type="button">Inspect supplied continuations</button></div>
<p id="status" class="status" role="status" aria-live="polite">Loading observations…</p></form></section>
<section class="panel" id="results" hidden><div class="result-grid"><div><div id="board" class="board" aria-label="Supplied chess position"></div><p id="legal" class="muted"></p><div id="tags" class="tags"></div></div><div>
<label>Conditional comparison<select id="comparison"></select></label><h2 id="verdict" style="margin-top:20px"></h2><div id="channels" class="channels"></div><p id="scope" class="muted"></p><div id="gaps"></div>
<details><summary>Branches and coverage</summary><pre id="coverage"></pre></details><details><summary>Model, runtime and evidence identities</summary><pre id="identities"></pre></details></div></div>
<div class="actions"><button id="graph" type="button">Inspect proof objects</button><button id="export" type="button">Download complete archive</button></div><p class="identity" id="handle"></p></section>
<section class="panel"><h2>Retrieve and reconstruct</h2><p class="muted">A proof handle remains available after restarting the inspector. A complete archive contains every object needed to reconstruct the original proof response.</p>
<label>Durable proof handle<input id="restore-handle" spellcheck="false" placeholder="proof-request:…"></label><div class="actions"><button id="restore" type="button">Retrieve stored summary</button></div>
<label>Downloaded proof archive<input id="archive-file" type="file" accept=".json,application/json"></label><div class="actions"><button id="reconstruct" type="button">Reconstruct and verify archive</button></div><p class="status" id="archive-status" role="status">No archive loaded.</p></section>
<section class="panel" id="proof-panel" hidden><h2>Content-addressed proof objects</h2><p class="muted">These shared objects index native evidence. Host storage does not create a conjunction proof or new independent evidence.</p><p id="page-status" class="status"></p><div class="proof-layout"><div id="nodes" class="nodes"></div><pre id="object-detail">Select an object.</pre></div><div class="actions"><button id="prev" type="button">Previous objects</button><button id="next" type="button">Next objects</button></div></section>
<footer>Relative observations · Separate native conditionals · Explicit uncertainty · Complete audit trail</footer></main>
<script>
const $=id=>document.getElementById(id);let catalog,selected,result,comparisons=[],pageOffset=0,nextOffset=null,lastArchiveRaw=null;
const pieces={k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟',K:'♔',Q:'♕',R:'♖',B:'♗',N:'♘',P:'♙'};
function text(tag,value,parent,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;parent.append(e);return e}
function showStatus(id,message,error=false){$(id).textContent=message;$(id).className='status'+(error?' error':'')}
function board(fen){$('board').replaceChildren();const ranks=fen.split(' ')[0].split('/');ranks.forEach((rank,y)=>{let x=0;for(const p of rank){if(/\d/.test(p)){for(let i=0;i<Number(p);i++)cell('',x++,y)}else cell(p,x++,y)}});function cell(p,x,y){const e=text('div',pieces[p]||'',$('board'),'square'+((x+y)%2?' dark':'')+(p&&p===p.toUpperCase()?' white-piece':''));e.setAttribute('aria-label',String.fromCharCode(97+x)+(8-y)+(p?' '+p:' empty'))}}
function choose(){selected=catalog.examples[Number($('example').value)];$('fen').value=selected.fen;$('move-a').value=selected.moves[0];$('move-b').value=selected.moves[1];$('source').textContent=selected.source+' · '+selected.split;$('responses-a').value=selected.branches?.A.slice(1).join(' ')||'';$('responses-b').value=selected.branches?.B.slice(1).join(' ')||'';$('response-source').textContent=selected.response_selection||'No registered continuation supplied.'}
async function request(url,options){const response=await fetch(url,options);const raw=await response.text();let data;try{data=JSON.parse(raw)}catch{throw Error('Server returned an unreadable response')}if(!response.ok)throw Error(data.error||'Request failed');return {data,raw,response}}
function render(){comparisons=result.comparisons?[{horizon:1,preference:result.immediate.preference},...result.comparisons]:[{horizon:1,preference:result.preference}];$('comparison').replaceChildren();comparisons.forEach((row,i)=>{const o=text('option',i===0?'Immediate consequences':row.horizon+' supplied plies · branches A'+(row.branches.A+1)+' / B'+(row.branches.B+1),$('comparison'));o.value=i});$('results').hidden=false;$('proof-panel').hidden=true;board(result.fen);$('handle').textContent=result.proof_handle;$('restore-handle').value=result.proof_handle;$('tags').replaceChildren();text('span',result.delivery.request_cache_hit?'Stored proof reused':'New native inspection',$('tags'),'tag');text('span','Full proof retained',$('tags'),'tag');$('coverage').textContent=JSON.stringify(result.branch_coverage||{horizon:1,scope:'Immediate endpoints only'},null,2);$('identities').textContent=JSON.stringify({models:result.model_versions,runtime:result.runtime_version,proof_root:result.proof_root,evidence:comparisons.map(r=>r.preference.evidence_ids)},null,2);renderComparison()}
function renderComparison(){const row=comparisons[Number($('comparison').value)||0],p=row.preference;$('verdict').textContent={'A-preferred':'Candidate A preferred','B-preferred':'Candidate B preferred',indeterminate:'Indeterminate comparison',incomplete:'Incomplete comparison'}[p.status]||p.status;$('channels').replaceChildren();for(const side of ['A','B','no-demonstrated-preference']){const c=p.channels[side],card=text('div','',$('channels'),'card');text('strong',side==='no-demonstrated-preference'?'No demonstrated preference':'Candidate '+side,card);text('div',c.raw_stv.strength.toFixed(4),card,'metric');text('small','Raw confidence '+c.raw_stv.confidence.toFixed(4),card);text('small',c.classification,card)}const legal=result.legality||result.immediate.legality;$('legal').textContent='Separate legality beliefs: A '+legal.A.classification+' · B '+legal.B.classification+'.';$('scope').textContent=(p.conditional_proof_complete?'Native conditional proof available':'No complete native conditional application')+' · joint strategic proof incomplete · '+row.horizon+' supplied ply/plies.';$('gaps').replaceChildren();for(const gap of p.gaps)text('p',gap,$('gaps'),'muted');if(result.unexamined_responses)text('p',result.unexamined_responses,$('gaps'),'muted')}
function branches(id,candidate){const lines=$(id).value.trim().split('\n').map(s=>s.trim()).filter(Boolean);return lines.length?lines.map(line=>[candidate,...line.split(/\s+/)]):[[candidate]]}
async function run(temporal){$('compare').disabled=$('continue').disabled=true;showStatus('status','Computing separate native evidence…');try{const fen=$('fen').value.trim(),payload={fen,preference_model:$('model').value,mode:$('mode').value,max_invocations:Number($('budget').value),unknown_squares:$('unknown').value.split(',').map(v=>v.trim()).filter(Boolean),view:'summary'};if(selected?.fen===fen&&selected.history)payload.history=selected.history;if(temporal){payload.branches={A:branches('responses-a',$('move-a').value.trim()),B:branches('responses-b',$('move-b').value.trim())};payload.horizons=[2,3];const registered=selected?.branches&&selected.fen===fen&&JSON.stringify(payload.branches)===JSON.stringify({A:[selected.branches.A],B:[selected.branches.B]});payload.selection_provenance=registered?selected.response_selection:'Explicit inspector-supplied lines'}else{payload.move_a=$('move-a').value.trim();payload.move_b=$('move-b').value.trim()}const response=await request(temporal?'/cycle14-continuations':'/cycle14-compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});result=response.data;window.plnCompactResult=result;window.plnCompactSummaryBytes=new TextEncoder().encode(response.raw).length;render();showStatus('status',result.execution.truncated?'Inspection incomplete · inspect work limits and gaps.':'Inspection finished · complete proof available on demand.')}catch(error){showStatus('status','Error: '+error.message,true)}finally{$('compare').disabled=$('continue').disabled=false}}
async function graph(offset){if(!result)return;showStatus('page-status','Loading proof objects…');$('proof-panel').hidden=false;try{const {data}=await request('/cycle14-proof?handle='+encodeURIComponent(result.proof_handle)+'&view=proof_graph&offset='+offset+'&limit=16');const page=data.proof_graph;pageOffset=page.offset;nextOffset=page.next_offset;$('nodes').replaceChildren();for(const node of page.nodes){const button=text('button',node.encoded[0]+' · '+node.id.slice(0,20)+'…',$('nodes'),'node');button.type='button';button.onclick=()=>{$('object-detail').textContent=JSON.stringify(node,null,2)}}if(page.nodes.length)$('object-detail').textContent=JSON.stringify(page.nodes[0],null,2);$('prev').disabled=offset===0;$('next').disabled=nextOffset===null;showStatus('page-status','Objects '+(offset+1)+'–'+(offset+page.nodes.length)+' of '+page.total+' · shared evidence occurrences preserved.')}catch(error){showStatus('page-status',error.message,true)}}
function download(bytes,name,type='application/json'){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
$('compare-form').onsubmit=e=>{e.preventDefault();run(false)};$('continue').onclick=()=>{if($('compare-form').reportValidity())run(true)};$('example').onchange=choose;$('comparison').onchange=renderComparison;$('graph').onclick=()=>graph(0);$('prev').onclick=()=>graph(Math.max(0,pageOffset-16));$('next').onclick=()=>{if(nextOffset!==null)graph(nextOffset)};
$('restore').onclick=async()=>{try{const {data}=await request('/cycle14-proof?handle='+encodeURIComponent($('restore-handle').value.trim()));result=data;window.plnCompactResult=result;render();showStatus('archive-status','Stored summary retrieved with its original proof identity.')}catch(error){showStatus('archive-status',error.message,true)}};
$('export').onclick=async()=>{if(!result)return;$('export').disabled=true;showStatus('archive-status','Collecting and checking the complete archive…');try{const {data,raw}=await request('/cycle14-proof?handle='+encodeURIComponent(result.proof_handle)+'&view=full_archive');lastArchiveRaw=raw;window.plnCompactArchive=data.archive;window.plnCompactArchiveRaw=raw;download(raw,'pln-cycle14-proof-archive.json');showStatus('archive-status','Complete archive downloaded · '+Object.keys(data.archive.objects).length+' shared objects.')}catch(error){showStatus('archive-status',error.message,true)}finally{$('export').disabled=false}};
$('reconstruct').onclick=async()=>{$('reconstruct').disabled=true;showStatus('archive-status','Reconstructing the downloaded archive in an empty proof store…');try{const file=$('archive-file').files[0],raw=file?await file.text():lastArchiveRaw;if(!raw)throw Error('Choose an archive file or download the current archive first.');const response=await fetch('/cycle14-expand',{method:'POST',headers:{'Content-Type':'application/json'},body:raw});if(!response.ok){const error=await response.json();throw Error(error.error||'Reconstruction failed')}const bytes=await response.arrayBuffer();const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');if(hash!==response.headers.get('X-Proof-Legacy-SHA256'))throw Error('Reconstructed byte identity mismatch');window.plnCompactReconstruction={sha256:hash,bytes:bytes.byteLength,root:response.headers.get('X-Proof-Root'),verified:true};download(bytes,'pln-cycle14-reconstructed-proof.json');showStatus('archive-status','Verified exact reconstruction · '+bytes.byteLength.toLocaleString()+' bytes · SHA-256 '+hash+'.')}catch(error){showStatus('archive-status',error.message,true)}finally{$('reconstruct').disabled=false}};
fetch('/cycle14-catalog').then(async response=>{const data=await response.json();if(!response.ok)throw Error(data.error);return data}).then(data=>{catalog=data;data.examples.forEach((row,i)=>{const option=text('option',row.id+(row.branches?' · supplied responses':''),$('example'));option.value=i});const names={'frozen-c13':'Frozen Cycle 13 relational model',empty:'Empty preference evidence','primary-immediate':'Cycle 14 registered immediate model','primary-temporal':'Cycle 14 registered temporal model'};for(const model of data.models){const option=text('option',names[model],$('model'));option.value=model}choose();showStatus('status','Ready · supply two candidates to inspect.');}).catch(error=>showStatus('status','Error: '+error.message,true));
</script></body></html>'''
